CREATE TYPE "Role" AS ENUM ('CLIENT','BARBER','ADMIN');
CREATE TYPE "AppointmentStatus" AS ENUM ('PENDING','CONFIRMED','CANCELED','COMPLETED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CLIENT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Barber" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"bio" TEXT,"experience" TEXT,"rating" DOUBLE PRECISION NOT NULL DEFAULT 0,"reviews" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "Barber_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Service" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"icon" TEXT,"category" TEXT NOT NULL,"price" DECIMAL(10,2) NOT NULL,"durationMinutes" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Service_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Schedule" ("id" TEXT NOT NULL,"barberId" TEXT NOT NULL,"weekday" INTEGER NOT NULL,"openTime" TEXT NOT NULL,"closeTime" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "Schedule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Appointment" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"barberId" TEXT,"serviceId" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"status" "AppointmentStatus" NOT NULL DEFAULT 'PENDING',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Appointment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserPreference" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"notifications" BOOLEAN NOT NULL DEFAULT true,"theme" TEXT NOT NULL DEFAULT 'dark',"locale" TEXT NOT NULL DEFAULT 'pt-BR',"haircutPreferences" JSONB,"notificationPreferences" JSONB,"paymentPreferences" JSONB,CONSTRAINT "UserPreference_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_phone_key" ON "User"("phone"); CREATE UNIQUE INDEX "Barber_userId_key" ON "Barber"("userId"); CREATE UNIQUE INDEX "Schedule_barberId_weekday_key" ON "Schedule"("barberId","weekday"); CREATE UNIQUE INDEX "UserPreference_userId_key" ON "UserPreference"("userId");
CREATE INDEX "Appointment_startsAt_endsAt_idx" ON "Appointment"("startsAt","endsAt"); CREATE INDEX "Appointment_userId_status_idx" ON "Appointment"("userId","status");
ALTER TABLE "Barber" ADD CONSTRAINT "Barber_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_barberId_fkey" FOREIGN KEY ("barberId") REFERENCES "Barber"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON UPDATE CASCADE; ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_barberId_fkey" FOREIGN KEY ("barberId") REFERENCES "Barber"("id") ON UPDATE CASCADE; ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON UPDATE CASCADE;
ALTER TABLE "UserPreference" ADD CONSTRAINT "UserPreference_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
